WITH cleaned AS (SELECT *, ROUND(amount * 1.1, 2) AS amount_scaled, DATE_FORMAT(paid_at, 'MMM yyyy') AS paid_at_label, COALESCE(method, 'OTHER') AS resolved_method FROM payments WHERE paid_at >= TIMESTAMP '2023-08-20 15:00:00' AND order_id IS NULL) SELECT id, order_id, method, amount, status, amount_scaled, paid_at_label, resolved_method, AVG(amount_scaled) OVER w_ordered AS amount_scaled_avg_3, PERCENT_RANK() OVER w_ordered_2 AS amount_percent_rank, NTILE(3) OVER (ORDER BY amount, id) AS amount_bucket, SUM(amount) OVER (PARTITION BY order_id ORDER BY amount, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS cumulative_amount, CUME_DIST() OVER w_recent AS amount_scaled_cume_dist FROM cleaned WINDOW w_ordered AS (PARTITION BY status ORDER BY amount, id ROWS BETWEEN 3 PRECEDING AND CURRENT ROW), w_ordered_2 AS (ORDER BY amount DESC NULLS FIRST), w_recent AS (PARTITION BY status ORDER BY amount_scaled NULLS LAST)
